INSERT INTO t_p31590366_multi_page_site_dev_.versions (version, date, type, title, description, full_description, changes, files, author_id) VALUES
('3.2.0', '2026-01-25', 'major', 'Крупное обновление: новый интерфейс администрирования', 'Полностью переработанный интерфейс с улучшенной производительностью', E'В этом крупном обновлении мы полностью переработали панель администрирования, сделав её более удобной и производительной.\n\nОсновной акцент был сделан на улучшение пользовательского опыта: новые виджеты, быстрые действия, обновлённая навигация. Система уведомлений теперь поддерживает push-уведомления и настраиваемые правила оповещений.\n\nТакже значительно улучшена работа с большими таблицами — виртуализация списков позволяет работать с десятками тысяч записей без задержек.', ARRAY['Новая панель администрирования', 'Улучшенная система уведомлений', 'Оптимизация работы с большими таблицами', 'Добавлен экспорт в Excel'], '[{"name": "Руководство_v3.2.0.pdf", "type": "pdf", "size": "2.4 MB"}, {"name": "Технические_спецификации.doc", "type": "doc", "size": "856 KB"}]'::jsonb, 1),

('3.1.5', '2026-01-15', 'patch', 'Исправление критических ошибок', 'Устранены проблемы с синхронизацией данных', E'Обновление направлено на устранение критических ошибок, обнаруженных после выпуска версии 3.1.0.\n\nГлавная проблема была связана с модулем отчётов, где в определённых сценариях данные отображались некорректно. Также была улучшена общая стабильность системы и обновлены зависимости.', ARRAY['Исправлена ошибка в модуле отчетов', 'Улучшена стабильность системы', 'Обновлены зависимости безопасности'], '[{"name": "Список_исправлений_v3.1.5.pdf", "type": "pdf", "size": "450 KB"}]'::jsonb, 1),

('3.1.0', '2026-01-01', 'minor', 'Новые возможности фильтрации', 'Расширенные инструменты для работы с данными', E'Версия 3.1.0 расширяет возможности работы с данными, добавляя продвинутые фильтры и новые форматы экспорта.\n\nПользователи теперь могут создавать сложные фильтры с несколькими условиями, сохранять их для повторного использования и делиться ими с коллегами.', ARRAY['Добавлены продвинутые фильтры', 'Новые виды экспорта данных', 'Улучшена производительность поиска'], '[{"name": "Руководство_фильтры.pdf", "type": "pdf", "size": "1.2 MB"}, {"name": "Примеры_использования.xls", "type": "xls", "size": "340 KB"}]'::jsonb, 1),

('3.0.0', '2025-12-15', 'major', 'Запуск версии 3.0: платформа нового поколения', 'Полный редизайн архитектуры и интерфейса системы', E'Версия 3.0 — это результат полугода работы над полной модернизацией платформы. Архитектура переведена на микросервисы.\n\nНовый интерфейс разработан с нуля по результатам UX-исследований. Время загрузки сократилось в 5 раз, а количество кликов для типовых операций уменьшилось на 40%.', ARRAY['Переход на микросервисную архитектуру', 'Полный редизайн интерфейса', 'API v3 с поддержкой GraphQL', 'Новая система аналитики и дашбордов', 'Мультиязычность интерфейса'], '[{"name": "Миграция_на_v3.pdf", "type": "pdf", "size": "3.1 MB"}, {"name": "API_документация_v3.pdf", "type": "pdf", "size": "1.8 MB"}]'::jsonb, 1),

('2.9.2', '2025-11-20', 'patch', 'Безопасность и стабильность', 'Обновление безопасности и устранение утечек памяти', E'Критическое обновление безопасности, закрывающее несколько уязвимостей в модуле аутентификации.\n\nТакже устранена утечка памяти при длительных сессиях работы с отчётами.', ARRAY['Закрыта уязвимость в модуле авторизации', 'Исправлена утечка памяти в генераторе отчётов', 'Обновлены SSL-сертификаты', 'Патч для совместимости с PostgreSQL 16'], '[{"name": "Security_advisory_2.9.2.pdf", "type": "pdf", "size": "280 KB"}]'::jsonb, 1),

('2.9.0', '2025-10-01', 'minor', 'Система уведомлений и интеграции', 'Встроенные уведомления и подключение внешних сервисов', E'Добавлена полноценная система уведомлений с поддержкой email, Telegram и webhook-интеграций.\n\nТакже реализована интеграция с популярными CRM-системами через REST API.', ARRAY['Система уведомлений (email, Telegram, webhooks)', 'Интеграция с CRM через API', 'Настраиваемые правила оповещений', 'Журнал уведомлений и история'], '[{"name": "Руководство_уведомления.pdf", "type": "pdf", "size": "980 KB"}, {"name": "API_интеграции.doc", "type": "doc", "size": "640 KB"}]'::jsonb, 1);